import {incrementalRecord} from './incremental-registry.js';
import {incrementalIdentityValid} from './incremental-research-identity.js';
import {evaluateUmc,UMC_OPERATING_COST_BASELINE} from './umc-financial-engine.js';
export const UMC_DRAFT_ERROR='UMC requires the complete June operating-assets model, explicit finite assumptions and nonnegative residual cash capex. Invalid inputs are retained; valuation is withheld.';
const finite=x=>typeof x==='number'&&Number.isFinite(x),object=x=>!!x&&typeof x==='object'&&!Array.isArray(x),fail=()=>{throw Error(UMC_DRAFT_ERROR);};
export function umcContext(d){
 try{
 const r=incrementalRecord(d?.ticker);if(!r||d.ticker!=='UMC'||!incrementalIdentityValid(d)||d.schemaVersion!==1||d.forecastHorizonYears!==10||!Array.isArray(d.annual)||d.annual.length!==10||Object.keys(d.annual).length!==10||d.timing?.mode!=='origin'||d.discountOrigin!=='2026-06-30'||d.timing.asOf!=='2026-10-19'||d.timing.stubFCFF!==null||!object(d.bridgeInputs)||Object.keys(d.bridgeInputs).length||d.umcPolicy===undefined)fail();
 if(['current_target','currentPriceTarget','current_price_target','selected_policy'].some(k=>d[k]!==undefined&&d[k]!==null))fail();
 if(!Array.isArray(d.umcDaNonlease)||d.umcDaNonlease.length!==10||Object.keys(d.umcDaNonlease).length!==10||!d.umcDaNonlease.every(v=>finite(v)&&v>=0))fail();
 const c=d.selectedIncrementalScenario?r.alternatives.find(a=>a.name===d.selectedIncrementalScenario)?.annualCase:r.annualCase;if(!c)fail();
 const p=d.umcPolicy??UMC_OPERATING_COST_BASELINE;let prior=d.anchor.revenue;
 const annual=d.annual.map((row,i)=>{
  if(!object(row)||row.year!==i+1||row.period!==c.annual[i].period||!['revenue','margin','taxRate','reinvestment','wacc'].every(k=>finite(row[k])))fail();
  const deltaNwc=(row.revenue-prior)*r.sourceInputs.incremental_working_capital_ratio;prior=row.revenue;
  const daNonlease=d.umcDaNonlease[i],supplementalOperatingCash=p.supplemental_operating_cash_by_year[i];
  return {revenue:row.revenue,margin:row.margin,taxRate:row.taxRate,reinvestment:row.reinvestment,wacc:row.wacc,cashCapex:row.reinvestment+daNonlease-deltaNwc-supplementalOperatingCash,daNonlease,leaseCash:p.lease_cash_by_year[i],deltaNwc,supplementalOperatingCash,financialCashInterest:p.financial_cash_interest_by_year[i]};
 });
 const result=evaluateUmc(r.sourceInputs,r.sourceInputs.scenarios[c.sourceScenario],d.umcPolicy,annual,d.terminal,r.fundingInputs);return {r,c,result,annual};
 }catch(error){const out=Object.assign(Error(UMC_DRAFT_ERROR),{status:"invalid_assumptions",enterprise:null,equity:null,perShare:null,current_target:null,current_price_target:null,conditional_usd_per_ads:null,conditional_twd_per_ordinary:null,cause:error});throw out;}
}
export function umcDraftIssues(d){if(d?.ticker!=='UMC')return [];return d.schemaVersion!==1||d.forecastHorizonYears!==10||d.timing?.mode!=='origin'||d.timing?.asOf!=='2026-10-19'||d.timing?.stubFCFF!==null||!Object.hasOwn(d,'umcPolicy')||['current_target','currentPriceTarget','current_price_target','selected_policy'].some(k=>d[k]!==undefined&&d[k]!==null)?[UMC_DRAFT_ERROR]:[];}
export function calculateUmcOperating(d){
 const {r,result:v}=umcContext(d);let prior=d.anchor.revenue,cumulative=0,trough=0;
 const rows=v.rows.map((row,i)=>{const delta=row.revenue-prior;prior=row.revenue;cumulative+=row.fcff;trough=Math.min(trough,cumulative);return {...d.annual[i],...row,period:d.annual[i].period,ebit:row.ebit_after_cash_lease,tax:row.cash_tax,discountFactor:row.discount_factor,pv:row.pv_fcff,cumulativeFCFF:cumulative,derivedSalesCapital:row.reinvestment?delta/row.reinvestment:null,enteredReinvestment:d.annual[i].reinvestment,requiredInvestment:null,investmentFloorTopUp:0};});
 return {ticker:'UMC',currency:'TWD',informationAsOf:d.informationAsOf,discountOrigin:d.discountOrigin,rows,terminal:{...v.terminal,fcffGrowth:rows.at(-1).fcff?v.terminal.fcff/rows.at(-1).fcff-1:null},forecastPV:v.forecastPV,terminalPV:v.terminalPV,enterprise:v.enterprise_value_twd_m,terminalShare:v.terminal_pv_fraction,peakEconomicDeficit:Math.max(0,-trough),negativeFCFFYears:rows.filter(x=>x.fcff<0).length,warnings:[r.prose.scope.en,r.prose.capital.en,r.prose.terminal.en,r.prose.funding.en],umcAllocation:v,classification:r.prose.scope.en,current_target:null,currentPriceTarget:null,selected_policy:v.selected_policy,currentValuationEligible:false,historicalBacktestEligible:false};
}
export function calculateUmcBridge(d,enterprise,options={}){
 const {r,result:v}=umcContext(d);if(Object.keys(options).some(k=>!['calculationDate','outputCurrency','securityBasis','informationAsOf'].includes(k))||options.calculationDate&&options.calculationDate!=='2026-06-30'||options.outputCurrency&&options.outputCurrency!=='TWD'||options.securityBasis&&options.securityBasis!=='ordinary-common'||options.informationAsOf&&options.informationAsOf!==d.informationAsOf||!finite(enterprise)||Math.abs(enterprise-v.enterprise_value_twd_m)>Math.max(1e-8,Math.abs(enterprise)*1e-10))fail();
 const eligible=v.conditional_twd_per_ordinary!==null,reason=v.selected_policy===null?r.prose.summary.en:r.prose.funding.en;
 return {ticker:'UMC',modelId:r.identity.version,currency:'TWD',moneyUnit:'millions',enterprise,operatingEV:enterprise,status:eligible?'conditional':'operating-only',eligible,perShare:v.conditional_twd_per_ordinary,rawPerShare:v.conditional_twd_per_ordinary,flooredPerShare:v.conditional_twd_per_ordinary,equity:eligible?v.equity_value_twd_m:null,conditional_usd_per_ads:v.conditional_usd_per_ads,conditional_twd_per_ordinary:v.conditional_twd_per_ordinary,current_target:null,currentPriceTarget:null,current_price_target:null,currentQuote:null,unconditionalPerShare:null,selected_policy:v.selected_policy,currentCapitalVerified:false,priceComparisonEligible:false,asKnownBacktestEligible:false,claimRepricedPerTrial:false,allocationLabel:r.prose.scope.en,classification:r.prose.scope.en,referenceDate:'2026-06-30',capitalReferenceDate:'2026-06-30',shareReferenceDate:'2026-06-30',fxDate:'2026-06-30',twdPerUsd:31.837,ordinaryPerADS:5,discountOrigin:d.discountOrigin,calculationDate:'2026-06-30',informationAsOf:d.informationAsOf,securityBasis:r.bridge.shareBasis,claimCompleteness:r.bridge.claimCompleteness,sources:[{url:r.bridge.sourceUrl,date:'2026-06-30'}],warnings:[r.prose.scope.en,r.prose.claims.en,r.prose.funding.en,r.prose.awards.en],unresolved:[r.prose.claims.en],reasons:eligible?[]:[reason],basicShares:r.sourceInputs.common_outstanding_million,allocationShares:v.ordinary_share_denominator_m,rows:[],inputs:{},optionDefinitions:[],umcAllocation:v};
}
export function umcSensitivity(d){const op=calculateUmcOperating(d);return {base:op.enterprise,normalized:op.enterprise,normalizationDelta:0,normalizedTerminalFCFFGrowth:op.terminal.fcffGrowth,normalizationLabel:incrementalRecord('UMC').prose.terminal.en,rates:[-.01,0,.01].map(shift=>{const next=structuredClone(d);next.annual.forEach(r=>r.wacc+=shift);next.terminal.wacc+=shift;try{return {waccShift:shift,wacc:next.terminal.wacc,enterprise:calculateUmcOperating(next).enterprise};}catch(e){return {waccShift:shift,wacc:next.terminal.wacc,enterprise:null,error:e.message};}})};}
